        cloudWire.json(blocks(original.document(),1)).json(blocks(original.document(),1)).json("{\"data\":[\"操作成功\",2]}").json(blocks("1\nspoiler keyword\n70003 oldname 70002",2));
        ok(cloudActions.setCloudBlock("70002","new user",true).confirmed,"cloud block confirms full independent document readback");NativeCommunity.Request cloudWrite=cloudWire.calls.get(cloudWire.calls.size()-2);ok("set_block_word".equals(cloudWrite.parameters.get("__act"))&&"1\nspoiler keyword\n70003 oldname 70002".equals(cloudWrite.parameters.get("data")),"cloud block preserves all existing keywords and other users");
        cloudWire.json(blocks("1\nspoiler keyword\n70003 70002/oldname username",3)).json(blocks("1\nspoiler keyword\n70003 70002/oldname username",3)).json("{\"data\":[\"操作成功\"]}").json(blocks("1\nspoiler keyword\n70003 username",4));cloudActions.setCloudBlock("70002","currentname",false);ok(!cloudWrite.parameters.containsKey("cookie"),"cloud author unblock uses own scoped session without serializing credentials");
