        cloudWire.json(blocks("1\nspoiler keyword\n70003 oldname",99));previousWrites=cloudWire.writes();try{cloudActions.saveCloudBlocks(original,"updated","70003");throw new AssertionError("expected cloud conflict");}catch(NativeCloudBlocks.ConflictException expected){checks++;}ok(previousWrites==cloudWire.writes(),"stale whole-list editor never overwrites another device update");
